def is_tr(hass): return str(getattr(hass.config,"language","") or "").lower().startswith("tr")
_NAMES={"online":("Çevrimiçi","Online"),"battery":("Pil","Battery"),"recognized_person":("Tanınan Kişi","Recognized Person"),"doorbell_status":("Kapı Zili Durumu","Doorbell Status"),"tamper_status":("Kurcalama Durumu","Tamper Status"),"high_temp_status":("Yüksek Sıcaklık Durumu","High Temperature Status"),"low_temp_status":("Düşük Sıcaklık Durumu","Low Temperature Status"),"pir_recording":("Hareket Algılandığında Kayıt","Record on Motion"),"tamper_recording":("Kurcalama Anında Kayıt","Record on Tamper"),"high_temp_alarm":("Yüksek Sıcaklık Alarmı","High Temperature Alarm"),"low_temp_alarm":("Düşük Sıcaklık Alarmı","Low Temperature Alarm"),"face_push":("Yüz Algılama Bildirimi","Face Detection Notification"),"anti_tamper_alarm":("Kurcalama Alarmı","Tamper Alarm"),"face_recording":("Yüz Algılandığında Kayıt","Record on Face Detection"),"privacy_mode":("Gizlilik Modu","Privacy Mode"),"doorbell_notification":("Kapı Zili Bildirimi","Doorbell Notification"),"doorbell_recording":("Kapı Zili Kaydı","Doorbell Recording"),"doorbell_volume":("Kapı Zili Sesi","Doorbell Volume"),"alarm_volume":("Alarm Sesi","Alarm Volume"),"camera_volume":("Kamera Sesi","Camera Volume"),"music_volume":("Müzik Sesi","Music Volume"),"system_volume":("Sistem Sesi","System Volume"),"alarm_duration":("Alarm Süresi","Alarm Duration"),"doorbell_duration":("Kapı Zili Süresi","Doorbell Duration"),"accidental_deletion":("Yanlışlıkla Silme Koruması","Accidental Deletion Prevention"),"restart_count":("Yeniden Başlatma Sayısı","Restart Count"),"restart_reason":("Yeniden Başlatma Nedeni","Restart Reason"),"wifi_channel":("Wi-Fi Kanalı","Wi-Fi Channel"),"binding_status":("Bağlantı Durumu","Binding Status"),"device_online_resource":("Cihaz Çevrimiçi Kaynağı","Device Online Resource"),"temperature":("Sıcaklık","Temperature"),"humidity":("Nem","Humidity"),"internal_temperature":("Dahili Sıcaklık","Internal Temperature"),"music_status":("Müzik Durumu","Music Status"),"alarm_status":("Alarm Durumu","Alarm Status"),"current_voltage":("Mevcut Voltaj","Current Voltage"),"low_battery":("Düşük Pil Durumu","Low Battery State"),"motion_detected":("Hareket Algılama Durumu","Motion Detection Status")}
_STATES={"clean":("Temiz","Clear"),"pressed":("Basıldı","Pressed"),"safe":("Güvenli","Safe"),"alarm":("Alarm","Alarm"),"ok":("İyi","OK"),"problem":("Problem","Problem"),"unknown_person":("Tanınmadı","Unknown"),"online":("Çevrimiçi","Online"),"offline":("Çevrimdışı","Offline"),"unknown":("Bilinmiyor","Unknown"),"detected":("Algılandı","Detected"),"not_detected":("Algılanmadı","Not detected"),"low":("Düşük","Low"),"normal":("Normal","Normal")}
def name(hass,key,fallback=None):
    v=_NAMES.get(key); return (v[0] if is_tr(hass) else v[1]) if v else (fallback or key)
def state(hass,key):
    v=_STATES.get(str(key),(str(key),str(key))); return v[0] if is_tr(hass) else v[1]
